// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount, bytes calldata data) public {
        amount = bound(amount, 0, type(uint128).max);
        Reverter target = new Reverter();
        vm.deal(address(c), amount);
        bool ok;
        try c.sendMoney(address(target), amount, data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "sendMoney must not revert even if the target reverts");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
